"""Signature-only vendored surface of capx YamTwoArmApi (generated from the capx source by an extraction script, since removed).

NO perception/Franka deps: the code-GT pipeline uses the API only for signatures (skill/program
validation), the API doc (actor prompt), and gripper-effect contracts (grounding) — nothing is
executed. Regenerate on cap-x API changes."""
import inspect

_SIGS = {'sample_grasp_pose': '(object_name, index=0)', 'get_object_pose': '(object_name, index=0, return_bbox_extent=False)', 'pick': '(object_name, arm)', 'place': '(object_name, target_name, arm)', 'grasp': '(object_name, arm)', 'release': '(arm)', 'hold': '(object_name, arm)', 'regrasp': '(object_name, arm)', 'insert': '(object_name, target_name, arm)', 'attach': '(object_name, target_name, arm)', 'handover': '(object_name, from_arm, to_arm)', 'rotate': '(object_name, angle_deg, arm)', 'screw': '(object_name, arm, turns=1, angle_deg=90.0)', 'unscrew': '(object_name, arm, turns=1, angle_deg=90.0)', 'press': '(target_name, arm)', 'goto_pose_arm0': '(position, quaternion_wxyz, z_approach=0.0)', 'goto_pose_arm1': '(position, quaternion_wxyz, z_approach=0.0)', 'goto_pose_both': '(position0, quaternion_wxyz0, position1, quaternion_wxyz1, z_approach=0.0)', 'get_arm0_gripper_pose': '()', 'get_arm1_gripper_pose': '()', 'open_gripper_arm0': '()', 'close_gripper_arm0': '()', 'open_gripper_arm1': '()', 'close_gripper_arm1': '()'}

DOCS = {'sample_grasp_pose': 'Sample a grasp pose for a named object via Contact-GraspNet.\n\nRuns detect -> segment -> point cloud -> Contact-GraspNet and returns the\nhighest-scoring grasp, transformed to world. Use this quaternion for grasping.\n\nArgs:\n    object_name: natural-language object name.\n    index: which detection candidate (by score) to grasp; use 0/1 to disambiguate\n        a left/right pair (e.g. two pot handles).\nReturns:\n    position: (3,) XYZ meters.  quaternion_wxyz: (4,) WXYZ grasp orientation.', 'get_object_pose': 'Locate a named object: segmented-point-cloud centroid (+ optional bbox extent).\n\nThe returned quaternion is UNRELIABLE for placement -- it is the gripper-down\norientation; use the position (and, for placement height, the extent).\n\nArgs:\n    object_name: natural-language object name.\n    index: which detection candidate (by score).\n    return_bbox_extent: also return the world-frame bbox extent (full side lengths).\nReturns:\n    position: (3,) XYZ meters.  quaternion_wxyz: (4,) gripper-down.\n    bbox_extent: (3,) meters if requested else None.', 'pick': 'Pick object_name up with arm: grasp then lift clear of the surface.\n\nArgs: object_name, arm ("left"|"right"). Returns True on success.', 'place': 'Place the object held by arm onto/at target_name, then release.\n\nMoves over target_name (gripper-down), lowers via standoff, opens, retreats.\nArgs: object_name (the held object, for grounding), target_name, arm.\nReturns True on success.', 'grasp': 'Grasp object_name with arm, in place (no lift).\n\nApproaches from a vertical standoff, closes the gripper on the sampled\ngrasp pose. Leaves the object held where it sits (use for regrasps / to set\nup a hold). Args: object_name, arm ("left"|"right"). Returns True on success.', 'release': 'Open arm\'s gripper and retreat vertically, freeing whatever it held.\n\nArgs: arm ("left"|"right"). Returns True on success.', 'hold': 'Grasp object_name with arm and keep it static as a fixture.\n\nSame motion as ``grasp`` but semantically marks arm as a holder while the\nOTHER arm manipulates against it (the dominant YAM bimanual pattern). Args:\nobject_name, arm ("left"|"right"). Returns True on success.', 'regrasp': 'Adjust arm\'s grip on object_name: open, lift slightly, re-grasp, close.\n\nArgs: object_name, arm ("left"|"right"). Returns True on success.', 'insert': 'Insert object_name into/onto receptacle target_name with arm.\n\nBest-effort general composition: grasp the object, lift clear, align above\nthe target, descend to the target opening, release, retreat.\nArgs: object_name, target_name, arm. Returns True on success.', 'attach': 'Affix the object held by arm onto target_name, then release.\n\nBest-effort general composition: place generalized with a seating/contact\nphase -- carry the held object over target_name (gripper-down), lower it via\nstandoff, press down ``_PRESS_DEPTH`` to seat/affix it, open, retreat. Use for\nstack / stick / clip / hang. Args: object_name (the held object), target_name,\narm ("left"|"right"). Returns True on success.', 'handover': 'Pass object_name from from_arm to to_arm, gripper-to-gripper.\n\nBest-effort general composition: from_arm picks the object and brings it to a\ntransfer pose (midpoint of the two grippers, at handover height); to_arm\ngrasps the object at its current pose; from_arm releases. (Collision-free\nhandover orientation / gap avoidance are task-specific and not modeled here.)\nArgs: object_name, from_arm, to_arm. Returns True on success.', 'rotate': 'Rotate the object held by arm in-hand by angle_deg about the gripper axis.\n\nBest-effort general composition: keeps the end-effector position fixed and\nre-orients the gripper by ``angle_deg`` about its own approach (local z) axis,\nturning the grasped object in place without regrasping. Args: object_name (the\nheld object), angle_deg, arm ("left"|"right"). Returns True on success.', 'screw': 'Screw/tighten object_name in place with arm: ``turns`` regrasp-turn cycles.\n\nEach cycle: grasp the object (CLOSE), wrist-turn by ``angle_deg`` about the\ngripper axis (as ``rotate``), let go (OPEN), wind the wrist back for the next\ngrip. Gripper effect = (CLOSE, OPEN) x turns. Use for screwing/twisting caps,\nknobs, taps in place; ``unscrew`` (or a negative angle_deg) loosens instead.\nArgs: object_name, arm ("left"|"right"), turns, angle_deg per turn.\nReturns True on success.', 'unscrew': 'Unscrew/loosen object_name with arm: ``screw`` with the opposite turn direction.\n\nGripper effect = (CLOSE, OPEN) x turns. Args as ``screw``. Returns True on success.', 'press': 'Press down on target_name with arm: approach from above, contact, retreat.\n\nBest-effort general composition: move over target_name\'s top surface\n(gripper-down), descend an extra ``_PRESS_DEPTH`` below it to make contact\n(there is no force control -- contact is commanded, not sensed), then retreat.\nUse for buttons / seating / tamping. Args: target_name, arm ("left"|"right").\nReturns True on success.', 'goto_pose_arm0': 'Go to pose using Inverse Kinematics for Arm 0 (robot0)\nArgs:\n    position: (3,) XYZ position in meters for arm 0.\n    quaternion_wxyz: (4,) WXYZ unit quaternion for arm 0.\n    z_approach: (float) Z-axis distance offset for goto_pose insertion approach motion. Will first arrive at position + z_approach meters in Z-axis before moving to the requested pose. Useful for more precise grasp approaches. Default is 0.0.\nReturns:\n    None', 'goto_pose_arm1': 'Go to pose using Inverse Kinematics for Arm 1 (robot1).\nArgs:\n    position: (3,) XYZ position in meters for arm 1.\n    quaternion_wxyz: (4,) WXYZ unit quaternion for arm 1.\n    z_approach: (float) Z-axis distance offset for goto_pose insertion approach motion. Will first arrive at position + z_approach meters in Z-axis before moving to the requested pose. Useful for more precise grasp approaches. Default is 0.0.\nReturns:\n    None', 'goto_pose_both': "Go to pose using Inverse Kinematics for moving both arms simultaneously. Positions and quaternions are in robot0's base frame.\nArgs:\n    position0: (3,) XYZ position in meters for arm 0.\n    quaternion_wxyz0: (4,) WXYZ unit quaternion for arm 0.\n    position1: (3,) XYZ position in meters for arm 1.\n    quaternion_wxyz1: (4,) WXYZ unit quaternion for arm 1.\n    z_approach: (float) Z-axis distance offset for goto_pose insertion approach motion. Will first arrive at position + z_approach meters in Z-axis before moving to the requested pose. Useful for more precise grasp approaches. Default is 0.0.\nReturns:\n    None", 'get_arm0_gripper_pose': 'Get the pose of the gripper for arm 0.\n\nArgs:\n    None\nReturns:\n    position: (3,) XYZ position in meters.\n    quaternion_wxyz: (4,) WXYZ unit quaternion.', 'get_arm1_gripper_pose': 'Get the pose of the gripper for arm 1.\n\nArgs:\n    None\nReturns:\n    position: (3,) XYZ position in meters.\n    quaternion_wxyz: (4,) WXYZ unit quaternion.', 'open_gripper_arm0': 'Open gripper fully for Arm 0 (robot0).\nArgs:\n    None\nReturns:\n    None', 'close_gripper_arm0': 'Close gripper fully for Arm 0 (robot0).\nArgs:\n    None\nReturns:\n    None', 'open_gripper_arm1': 'Open gripper fully for Arm 1 (robot1).\nArgs:\n    None\nReturns:\n    None', 'close_gripper_arm1': 'Close gripper fully for Arm 1 (robot1).\nArgs:\n    None\nReturns:\n    None'}

GRIPPER_EFFECTS = {'close_gripper_arm0': [('left', 'close')], 'open_gripper_arm0': [('left', 'open')], 'close_gripper_arm1': [('right', 'close')], 'open_gripper_arm1': [('right', 'open')], 'grasp': [('arm', 'close')], 'pick': [('arm', 'close')], 'hold': [('arm', 'close')], 'place': [('arm', 'open')], 'release': [('arm', 'open')], 'attach': [('arm', 'open')], 'regrasp': [('arm', 'open'), ('arm', 'close')], 'insert': [('arm', 'close'), ('arm', 'open')], 'handover': [('from', 'close'), ('to', 'close'), ('from', 'open')]}

def _make(name, sig, doc):
    ns = {}
    exec('def ' + name + sig + ': pass', ns)
    f = ns[name]; f.__doc__ = doc or None
    return f

FUNCTIONS = {name: _make(name, _SIGS[name], DOCS.get(name, '')) for name in _SIGS}

def gripper_effects(name, args=None):
    if name in ('screw', 'unscrew'):
        try: turns = max(int((args or {}).get('turns', 1)), 1)
        except (TypeError, ValueError): turns = 1
        return [('arm', 'close'), ('arm', 'open')] * turns
    return GRIPPER_EFFECTS.get(name)

def _combined_doc():
    lines = []
    for name, fn in FUNCTIONS.items():
        lines.append(name + str(inspect.signature(fn)))
        doc = fn.__doc__ or ''
        if doc:
            lines.append('  Doc:')
            lines.extend('    ' + ln for ln in doc.splitlines())
        lines.append('')
    return '\n'.join(lines).strip()

COMBINED_DOC = _combined_doc()
